+/* Only these entry points expose shared state to the request thread. */
+int load_accelerator(const char *name)
+{
+    int ret;
+    if (!name || !name[0])
+        return -1;
+    pthread_mutex_lock(&state_lock);
+    ret = load_accelerator_locked(name);
+    pthread_mutex_unlock(&state_lock);
+    return ret;
+}
