	memcpy (ctx->Iv, iv, AES_BLOCKLEN);
}
void AES_ctx_set_iv(struct AES_ctx* ctx, const uint8_t* iv)
{
	memcpy (ctx->Iv, iv, AES_BLOCKLEN);
}
