int file2json(char* filename, Json_t *json){
	FILE *f = fopen(filename, "rb");
	fseek(f, 0, SEEK_END);
	json->size = ftell(f);
	fseek(f, 0, SEEK_SET);

	json->data = malloc(json->size + 1);
	int len = fread(json->data, json->size, 1, f);
	_unused(len);
	fclose(f);
	json->data[json->size] = 0;
	INFO("%s\n", json->data);
	return 0;
}

